root@5ec6d299675a:/app# export GIT_PAGER=cat PAGER=cat GIT_TERMINAL_PROMPT=0
root@5ec6d299675a:/app# sqlite3 /app/oewn.sqlite '.tables' && sqlite3 /app/oewn.sqlite '.schema' | sed -n '1,240p'
adjpositions          morphs                senses_vframes
casedwords            poses                 senses_vtemplates
domains               pronunciations        synsets
ilis                  relations             usages
lexes                 samples               vframes
lexes_morphs          semrelations          vtemplates
lexes_pronunciations  senses                wikidatas
lexrelations          senses_adjpositions   words
CREATE TABLE `synsets` (
`synsetid` INT NOT NULL,
`posid` CHARACTER (1) CHECK( `posid` IN ('n','v','a','r','s') ) NOT NULL,
`domainid` INT NOT NULL,
`definition` MEDIUMTEXT NOT NULL
);
CREATE TABLE `words` (
`wordid` INT NOT NULL,
`word` VARCHAR(80) NOT NULL
);
CREATE TABLE `casedwords` (
`casedwordid` INT NOT NULL,
`wordid` INT NOT NULL ,
`casedword` VARCHAR(80) NOT NULL
);
CREATE TABLE `pronunciations` (
`pronunciationid` INT NOT NULL,
`pronunciation` VARCHAR(50) NOT NULL
);
CREATE TABLE `morphs` (
`morphid` INT NOT NULL,
`morph` VARCHAR(70) NOT NULL
);
CREATE TABLE `poses` (
`posid` CHARACTER (1) CHECK( `posid` IN ('n','v','a','r','s') ) NOT NULL,
`pos` VARCHAR(20) NOT NULL
);
CREATE TABLE `relations` (
`relationid` INT NOT NULL,
`relation` VARCHAR(50) NOT NULL,
`recurses` TINYINT(1) NOT NULL
);
CREATE TABLE `domains` (
`domainid` INT NOT NULL,
`domain` VARCHAR(32) NOT NULL,
`domainname` VARCHAR(32) NOT NULL,
`posid` CHARACTER (1) CHECK( `posid` IN ('n','v','a','r','s') ) NOT NULL
);
CREATE TABLE `samples` (
`sampleid` INT NOT NULL,
`sample` MEDIUMTEXT NOT NULL,
`source` MEDIUMTEXT NULL,
`synsetid` INT NOT NULL,
`luid` INT DEFAULT NULL,
`wordid` INT DEFAULT NULL
);
CREATE TABLE `vframes` (
`frameid` INT NOT NULL,
`frame` VARCHAR(50) NOT NULL
);
CREATE TABLE `vtemplates` (
`templateid` INT NOT NULL,
`template` MEDIUMTEXT NOT NULL
);
CREATE TABLE `adjpositions` (
`positionid` CHARACTER (1) CHECK( `positionid` IN ('a','p','ip') ) NOT NULL,
`position` VARCHAR(24) NOT NULL
);
CREATE TABLE `lexes` (
`luid` INT NOT NULL,
`posid` CHARACTER (1) CHECK( `posid` IN ('n','v','a','r','s') ) NOT NULL,
`wordid` INT NOT NULL,
`casedwordid` INT DEFAULT NULL
);
CREATE TABLE `senses` (
`senseid` INT NOT NULL,
`sensekey` VARCHAR(100) DEFAULT NULL,
`synsetid` INT NOT NULL,
`luid` INT NOT NULL,
`wordid` INT NOT NULL,
`casedwordid` INT DEFAULT NULL,
`lexid` INT NOT NULL,
`sensenum` INT DEFAULT NULL,
`tagcount` INT DEFAULT NULL
);
CREATE TABLE `lexes_morphs` (
`luid` INT NOT NULL,
`wordid` INT NOT NULL,
`posid` CHARACTER (1) CHECK( `posid` IN ('n','v','a','r','s') ) NOT NULL,
`morphid` INT NOT NULL
);
CREATE TABLE `lexes_pronunciations` (
`luid` INT NOT NULL,
`wordid` INT NOT NULL,
`posid` CHARACTER (1) CHECK( `posid` IN ('n','v','a','r','s') ) NOT NULL,
`pronunciationid` INT NOT NULL,
`variety` VARCHAR(2) DEFAULT NULL
);
CREATE TABLE `senses_adjpositions` (
`synsetid` INT NOT NULL,
`luid` INT NOT NULL,
`wordid` INT NOT NULL,
`positionid` CHARACTER (1) CHECK( `positionid` IN ('a','p','ip') ) NOT NULL
);
CREATE TABLE `lexrelations` (
`synset1id` INT NOT NULL,
`lu1id` INT NOT NULL,
`word1id` INT NOT NULL,
`synset2id` INT NOT NULL,
`lu2id` INT NOT NULL,
`word2id` INT NOT NULL,
`relationid` INT NOT NULL
);
CREATE TABLE `senses_vframes` (
`synsetid` INT NOT NULL,
`luid` INT NOT NULL,
`wordid` INT NOT NULL,
`frameid` INT NOT NULL
);
CREATE TABLE `senses_vtemplates` (
`synsetid` INT NOT NULL,
`luid` INT NOT NULL,
`wordid` INT NOT NULL,
`templateid` INT NOT NULL
);
CREATE TABLE `semrelations` (
`synset1id` INT NOT NULL,
`synset2id` INT NOT NULL,
`relationid` INT NOT NULL
);
CREATE TABLE `usages` (
`usageid` INT NOT NULL,
`usagenote` MEDIUMTEXT NOT NULL,
`synsetid` INT NOT NULL,
`luid` INT DEFAULT NULL,
`wordid` INT DEFAULT NULL
);
CREATE TABLE `ilis` (
`ili` VARCHAR(7) NOT NULL,
`synsetid` INT NOT NULL
);
CREATE TABLE `wikidatas` (
`wikidata` VARCHAR(12) NOT NULL,
`synsetid` INT NOT NULL
);
root@5ec6d299675a:/app# true; tmux wait -S done
root@5ec6d299675a:/app#

function.arguments:
{"command": "sqlite3 /app/oewn.sqlite <<'SQL'
.timer on
SELECT 'words', count(*) FROM words;
SELECT 'senses', count(*) FROM senses;
SELECT 'synsets', count(*) FROM synsets;
SELECT 'distinct sense word/synset', count(*) FROM (SELECT DISTINCT wordid, synsetid FROM senses);
SELECT 'duplicate word/synset groups', count(*) FROM (SELECT wordid, synsetid, count(*) c FROM senses GROUP BY wordid, synsetid HAVING c>1);
SQL"}

{"command":"sqlite3 /app/oewn.sqlite <<'SQL'
SELECT 'duplicate words.wordid', count(*) FROM (SELECT wordid FROM words GROUP BY wordid HAVING count(*)>1);
SELECT 'duplicate synsets.synsetid', count(*) FROM (SELECT synsetid FROM synsets GROUP BY synsetid HAVING count(*)>1);
SELECT sqlite_version();
SQL"}
